import json
p=json.load(open('canonical-input.json'))
print('ORIGINAL/CANDIDATE DIFFERENCES')
def diff(a,b,path=''):
 if type(a)"'!=type(b):
  print(path,repr(a),'"'->',repr(b))
 elif isinstance(a,dict):
  for k in sorted(set(a)|set(b)):
   if k not in a or k not in b: print(path+'/'+k, 'only in one')
   else: diff(a[k],b[k],path+'/'+k)
 elif a"'!=b:
  print(path+'"'\\nORIGINAL: '+json.dumps(a,ensure_ascii=False)+'\\nCANDIDATE: '+json.dumps(b,ensure_ascii=False))
diff(p['original'],p['candidate'])
print('\\nRECOGNITION\\n'+json.dumps(p['currentHessianEntryAndRecognition'],ensure_ascii=False,indent=2))
PY"

